function slugify(name: string) {
  return name.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
}

function foodFor(state: string, city: string) {
  const map: Record<string, string> = {
    'Rajasthan': 'Dal Baati Churma thali with ghee',
    'Gujarat': 'Gujarati thali with farsan and undhiyu (seasonal)',
    'Punjab': 'Amritsari kulcha, dal makhani, and lassi',
    'Maharashtra': 'Misal pav, vada pav, or vegetarian thali',
    'Goa': 'Goan vegetarian thali or seafood catch of the day',
    'Kerala': 'Kerala sadhya on a banana leaf with payasam',
    'Tamil Nadu': 'Banana-leaf meals, filter coffee, and dosa',
    'Karnataka': 'Bisi bele bath, Mysore pak, and filter coffee',
    'West Bengal': 'Vegetarian thali with mishti doi or kosha',
    'Uttar Pradesh': 'Awadhi vegetarian thali, chaat, and lassi',
    'Delhi': 'Chole bhature, chaat, and Old Delhi sweets',
    'Telangana': 'Hyderabadi vegetarian thali or irani chai + Osmania',
    'Andhra Pradesh': 'Andhra meals with gongura and pulihora',
    'Odisha': 'Dalma, chhena poda, and temple mahaprasad',
    'Assam': 'Assamese thali with khar, tenga, and pithas',
    'Himachal Pradesh': 'Dham thali, siddu, and sweet chai',
    'Uttarakhand': 'Aloo ke gutke, chainsoo, and pahadi thali',
    'Jammu & Kashmir': 'Kashmiri wazwan vegetarian wazwan / nadru',
    'Ladakh': 'Thukpa, momos, and butter tea',
    'Meghalaya': 'Jadoh (ask for vegetarian variants) and pu-thep',
    'Sikkim': 'Phagshapa-free thukpa, momos, and sel roti',
    'Puducherry': 'Creole-Tamil fusion and filter coffee'
  };
  return map[state] || `Regional ${city} vegetarian thali and street snacks`;
}

function autoClusters(c: CompactIndianCity): NonNullable<CompactIndianCity['clusters']> {
  const a = c.attractions;
  return [
    {
      name: `${c.city} Heritage & Landmark Core`,
      hub: `Central ${c.city}`,
      adv: `Primary sights of ${c.city} are grouped into one walkable/short-hop quadrant to avoid cross-town traffic.`,
      walk: 2.0,
      transport: 'Walking, auto-rickshaw, or app taxi within the cluster',
      m: a[0] || `${c.city} landmark morning visit`,
      l: foodFor(c.state, c.city),
      a: a[1] || `${c.city} museum, bazaar, or viewpoint`,
      e: a[2] || `${c.city} sunset point, aarti, or night market`,
      mt: `Arrive at opening time to beat both heat and queues in ${c.city}.`,
      lt: 'Ask for a local vegetarian thali — India shines at midday meals.',
      at: 'Keep a scarf/dupatta handy for temple dress codes.',
      et: 'Pre-book the return auto at dusk; carry small cash.'
    },
    {
      name: `${c.city} Neighbourhoods, Crafts & Cuisine`,
      hub: `${c.city} old bazaar / new town`,
      adv: `Second-day cluster stays inside ${c.state} craft and food streets without repeating Day 1 monuments.`,
      walk: 2.2,
      m: a[3] || `${c.city} crafts quarter & local market`,
      l: `${c.city} café hop or regional sweets tasting`,
      a: a[4] || `Park, lake, or hill viewpoint on the edge of ${c.city}`,
      e: `Evening cultural show, promenade, or rooftop in ${c.city}`,
      mt: 'Markets are liveliest before noon and after 5 PM.',
      lt: 'Sample two small plates rather than one heavy meal.',
      at: 'Golden hour is the best (and coolest) photography window.',
      et: 'Confirm last metro/bus times if not using an app cab.'
    }
  ];
}

function slotFrom(
  title: string,
  category: 'Culture' | 'Dining' | 'Sightseeing' | 'Leisure' | 'Adventure' | 'Nightlife',
  description: string,
  tip: string,
  costUsd: number,
  tags: string[]
) {
  return {
    title,
    category,
    description,
    costUsd,
    costInr: Math.round(costUsd * 84.5),
    tags,
    tip
  };
}

export function buildIndianDestinations(): DestinationPreset[] {
  return INDIA_CITIES.map((c) => {
    const clustersSrc = (c.clusters && c.clusters.length > 0 ? c.clusters : autoClusters(c));
    const clusters = clustersSrc.map((cl) => ({
      clusterName: cl.name,
      hubArea: cl.hub,
      transitAdvantage: cl.adv,
      walkingRadiusKm: cl.walk ?? 2,
      recommendedTransport: cl.transport || 'Walking + auto-rickshaw / Uber-Ola',
      sampleMorning: slotFrom(cl.m, 'Culture', `Start your ${c.city} morning at ${cl.m} while the light is soft and crowds are thin.`, cl.mt || 'Arrive early.', cl.mc ?? 8, c.tags.slice(0, 3)),
      sampleLunch: slotFrom(cl.l, 'Dining', `Pause for ${cl.l} — a flavour snapshot of ${c.state}.`, cl.lt || 'Ask for the house thali.', cl.lc ?? 10, ['Local Food', 'Vegetarian Friendly']),
      sampleAfternoon: slotFrom(cl.a, 'Sightseeing', `Continue inside the same cluster with ${cl.a}.`, cl.at || 'Carry water and a hat.', cl.ac ?? 8, c.tags),
      sampleEvening: slotFrom(cl.e, 'Leisure', `Wind down with ${cl.e} as ${c.city} lights up.`, cl.et || 'Keep small notes for autos.', cl.ec ?? 12, ['Evening', 'Atmosphere'])
    }));

    return {
      id: `india-${slugify(c.city)}`,
      city: c.city,
      country: 'India',
      vibe: c.vibe,
      budgetTier: c.budget,
      dailyCostUsd: c.dailyUsd,
      dailyCostInr: Math.round(c.dailyUsd * 84.5),
      localCurrencyCode: 'INR',
      localCurrencySymbol: '₹',
      exchangeRateUsdToLocal: 84.5,
      bestSeasons: c.seasons,
      weatherSummary: c.weather,
      highlightTags: c.tags,
      topAttractions: c.attractions,
      description: c.blurb,
      imageUrl: c.image,
      transitScore: c.transit,
      clusters,
      emergencyContacts: {
        ...INDIA_EMERGENCY,
        nearestMedicalHub: c.hospital
      },
      packingList: INDIA_PACKING,
      transitGuidelines: INDIA_TRANSIT,
      state: c.state,
      aliases: c.aliases || []
    } as DestinationPreset;
  });
}

export const INDIAN_CITY_INDEX = INDIA_CITIES.map((c) => ({
  city: c.city,
  state: c.state,
  vibe: c.vibe,
  aliases: c.aliases || []
})).sort((a, b) => a.city.localeCompare(b.city));

export const INDIAN_STATES = Array.from(new Set(INDIA_CITIES.map((c) => c.state))).sort();
